import{_ as e,o as d,c as r,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const p=JSON.parse('{"title":"练习路线：从零重建你的技术分析引擎","description":"","frontmatter":{"title":"练习路线：从零重建你的技术分析引擎"},"headers":[],"relativePath":"a-share-investing-course/exercises.md","filePath":"a-share-investing-course/docs/exercises.md"}'),s={name:"a-share-investing-course/exercises.md"};function o(c,t,n,i,l,h){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="练习路线-从零重建你的技术分析引擎" tabindex="-1">练习路线：从零重建你的技术分析引擎 <a class="header-anchor" href="#练习路线-从零重建你的技术分析引擎" aria-label="Permalink to &quot;练习路线：从零重建你的技术分析引擎&quot;">​</a></h1><p>读完本课程，最强的验证方式不是再做一遍笔记，而是把引擎删掉重写一遍。实验场的测试是按章解锁的作业梯子：每章的测试文件就是那章的目标规格，你从零实现 <code>src/</code>，让测试逐章从红转绿。</p><h2 id="玩法三步" tabindex="-1">玩法三步 <a class="header-anchor" href="#玩法三步" aria-label="Permalink to &quot;玩法三步&quot;">​</a></h2><ol><li><strong>拿到骨架</strong>：进入 <code>companion/</code>，跑 <code>npm install</code>（一次性）；然后清空 <code>src/</code>（保留 <code>tests/</code> 与 <code>scripts/</code>）。</li><li><strong>按章转绿</strong>：从第 3 章的 <code>tests/candle-anatomy.test.ts</code> 开始，跑 <code>npm test</code> 看它红着，按第 3 章正文重写 <code>src/candles/</code> 与 <code>src/data/</code>，直到这份测试变绿；再进入下一章的测试文件。旧章测试持续全绿，就是你自己版本的 API 兼容哨兵——后章实现破坏前章行为时，红的是你，不是书。</li><li><strong>对照终态</strong>：本课程测试都绿后（应为 430 项），你的实现与课程终态在行为上等价；写法不同完全正常——测试断言的是行为，不是实现细节。</li></ol><p>不打算写代码？这条路可以整个跳过：每章正文末尾的「验证」小节（纸笔跟算 + 手机实操）就是不进实验场的读者的完整练习路线，配合两张速查表同样能走完本课程。</p><h2 id="各章测试-↔-教的什么" tabindex="-1">各章测试 ↔ 教的什么 <a class="header-anchor" href="#各章测试-↔-教的什么" aria-label="Permalink to &quot;各章测试 ↔ 教的什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>测试文件</th><th>章</th><th>你要重建的能力</th></tr></thead><tbody><tr><td><code>auction-matching.test.ts</code></td><td><a href="./02-order-journey.html">第 2 章</a></td><td>集合竞价最大成交量定价与成交分配</td></tr><tr><td><code>candle-anatomy.test.ts</code></td><td><a href="./03-candle-anatomy.html">第 3 章</a></td><td>逐笔聚合成 K 线、周期聚合、实体影线占比</td></tr><tr><td><code>candle-rendering.test.ts</code></td><td><a href="./04-candle-rendering.html">第 4 章</a></td><td>OHLC 到像素的几何映射</td></tr><tr><td><code>single-patterns-wicks.test.ts</code></td><td><a href="./05-single-patterns-wicks.html">第 5 章</a></td><td>影线族七形态与位置换名</td></tr><tr><td><code>single-patterns-doji.test.ts</code></td><td><a href="./06-single-patterns-doji.html">第 6 章</a></td><td>十字族六分类与犹豫分级</td></tr><tr><td><code>multi-patterns-two.test.ts</code></td><td><a href="./07-multi-patterns-two.html">第 7 章</a></td><td>九种双根形态</td></tr><tr><td><code>multi-patterns-three.test.ts</code></td><td><a href="./08-multi-patterns-three.html">第 8 章</a></td><td>七种多根形态与确认层</td></tr><tr><td><code>pattern-stats.test.ts</code></td><td><a href="./09-pattern-stats.html">第 9 章</a></td><td>胜率/基准/随机对照验货</td></tr><tr><td><code>moving-averages.test.ts</code></td><td><a href="./11-moving-averages.html">第 11 章</a></td><td>SMA/EMA/金叉死叉</td></tr><tr><td><code>volume-analysis.test.ts</code></td><td><a href="./12-volume-analysis.html">第 12 章</a></td><td>量能标签与量价背离</td></tr><tr><td><code>support-resistance.test.ts</code></td><td><a href="./13-support-resistance.html">第 13 章</a></td><td>枢轴、聚类成位、斐波那契</td></tr><tr><td><code>chip-distribution.test.ts</code></td><td><a href="./14-chip-distribution.html">第 14 章</a></td><td>换手衰减筹码模型</td></tr><tr><td><code>reversal-structures.test.ts</code></td><td><a href="./15-reversal-structures.html">第 15 章</a></td><td>头肩/双顶结构与量度目标</td></tr><tr><td><code>macd.test.ts</code></td><td><a href="./16-macd.html">第 16 章</a></td><td>MACD 三层与背离检测</td></tr><tr><td><code>rsi-kdj.test.ts</code></td><td><a href="./17-rsi-kdj.html">第 17 章</a></td><td>RSI/KDJ 与钝化断言</td></tr><tr><td><code>bollinger.test.ts</code></td><td><a href="./18-bollinger.html">第 18 章</a></td><td>布林带/收口/带外统计</td></tr><tr><td><code>expectancy-risk.test.ts</code></td><td><a href="./20-expectancy-risk.html">第 20 章</a></td><td>期望值/凯利/破产概率</td></tr><tr><td><code>backtest-engine.test.ts</code></td><td><a href="./21-backtest-engine.html">第 21 章</a></td><td>含费用与 T+1 的回测引擎</td></tr></tbody></table><p>第 1、10、19、22 章是原理章，没有测试文件——它们的「作业」在正文末尾的自查问里。</p><h2 id="两个提醒" tabindex="-1">两个提醒 <a class="header-anchor" href="#两个提醒" aria-label="Permalink to &quot;两个提醒&quot;">​</a></h2><ul><li>卡住时先回正文：每章「渐进实验」段贴的代码就是这份测试的实现路径图，标注出处的代码块与终态逐字一致。</li><li>重写完跑一遍 <code>npm run export-docs</code>：如果它还能产出全部图表数据且两次运行字节一致，说明你的确定性纪律（固定种子、无时间戳）也过关了。</li></ul>',10)])])}const u=e(s,[["render",o]]);export{p as __pageData,u as default};
